#!/usr/bin/env bash
# Create or maintain deploy/.env with generated and placeholder secrets.
source "$(dirname "$0")/../lib/common.sh"

require_not_root

if [ ! -f "$ENV_FILE" ]; then
  log_info "Creating $ENV_FILE from template…"
  cat >"$ENV_FILE" <<EOF
# Mira Review Bot — production environment (generated by scripts/app/gen-secrets.sh)
# Edit USER-SUPPLIED values before running scripts/app/up.sh.

# ── USER-SUPPLIED (fill in before starting the stack) ────────────────────────
CURSOR_API_KEY=
GITLAB_BASE_URL=https://gitlab.example.com
GITLAB_TOKEN=
GITLAB_WEBHOOK_SECRET=
KAITEN_BASE_URL=https://your-space.kaiten.ru
KAITEN_TOKEN=
MIRA_PUBLISHER=log

# ── INFRA (sensible defaults; override if needed) ────────────────────────────
MIRA_BASE=${MIRA_BASE}
POSTGRES_USER=mira
POSTGRES_DB=mira
MAX_CONCURRENCY=1
POLL_INTERVAL_MS=60000
HEALTH_PUBLISH=127.0.0.1:8080

# ── GENERATED (do not rotate POSTGRES_PASSWORD after the DB is initialized) ──
POSTGRES_PASSWORD=$(gen_password)
REDIS_PASSWORD=$(gen_password)
EOF
  log_ok "Created $ENV_FILE with generated Postgres/Redis passwords."
else
  log_info "$ENV_FILE already exists — will not overwrite."

  _ensure_generated_secret() {
    local key="$1"
    local value
    value="$(env_get "$key" 2>/dev/null || true)"
    if [ -n "$value" ]; then
      log_warn "$key is already set — leaving unchanged (rotating after DB init breaks auth)."
      return 0
    fi
    value="$(gen_password)"
    {
      printf '\n# ── GENERATED (added by gen-secrets.sh) ─────────────────────────────────────\n'
      printf '%s=%s\n' "$key" "$value"
    } >>"$ENV_FILE"
    log_ok "Appended $key to $ENV_FILE."
  }

  _ensure_generated_secret POSTGRES_PASSWORD
  _ensure_generated_secret REDIS_PASSWORD
fi

chmod 600 "$ENV_FILE"
log_ok "Permissions set to 600 on $ENV_FILE."

missing=()
for key in CURSOR_API_KEY GITLAB_BASE_URL GITLAB_TOKEN KAITEN_BASE_URL KAITEN_TOKEN; do
  if [ -z "$(env_get "$key" 2>/dev/null || true)" ]; then
    missing+=("$key")
  fi
done

if [ "${#missing[@]}" -gt 0 ]; then
  log_warn "The following USER-SUPPLIED secrets are still empty: ${missing[*]}"
  log_warn "Edit $ENV_FILE and fill them in before running scripts/app/up.sh."
else
  log_ok "All required USER-SUPPLIED secrets are present."
fi

cat <<EOF

Next step
─────────
Edit $ENV_FILE — fill in GitLab, Kaiten, and Cursor credentials, then:
  scripts/app/up.sh

EOF
